use jobrunner::{run_job, RetryConfig, RetryError, Sleeper};

#[derive(Default)]
struct RecordingSleeper(Vec<u64>);

impl Sleeper for RecordingSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.0.push(ms);
    }
}

#[test]
fn public_api_retries_transient_failures_and_preserves_signature() {
    let config = RetryConfig {
        max_attempts: 3,
        base_delay_ms: 7,
        max_delay_ms: 10,
    };
    let mut sleeper = RecordingSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        match calls {
            1 | 2 => Err(RetryError::Transient("temporary".to_owned())),
            _ => Ok(()),
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.0, vec![7, 10]);
}

